  | "email"
  | "phone"
  | "ip"
  | "credit-card"
  | "api-key"
  | "custom";

/**
 * Representation of a PII detection or redaction rule.
 * For native model-backed rules, pattern and mask are optional.
 * For regex-based overlay rules (e.g. api-key-generic), pattern and mask are provided.
